35	function stripStringsAndComments(source) {
36	  let out = "";
37	  for (let i = 0; i < source.length;) {
38	    const ch = source[i];
39	    const next = source[i + 1];
40	    if (ch === "/" && next === "/") {
41	      out += "  ";
42	      i += 2;
43	      while (i < source.length && source[i] !== "\n") {
44	        out += " ";
45	        i += 1;
46	      }
47	      continue;
48	    }
49	    if (ch === "/" && next === "*") {
50	      out += "  ";
51	      i += 2;
52	      while (i < source.length && !(source[i] === "*" && source[i + 1] === "/")) {
53	        out += source[i] === "\n" ? "\n" : " ";
54	        i += 1;
55	      }
56	      if (i < source.length) {
57	        out += "  ";
58	        i += 2;
59	      }
60	      continue;
61	    }
62	    if (ch === "\"" || ch === "'" || ch === "`") {
63	      const quote = ch;
64	      out += " ";
65	      i += 1;
66	      while (i < source.length) {
67	        if (source[i] === "\\") {
68	          out += " ";
69	          i += 1;
70	          if (i < source.length) {
71	            out += source[i] === "\n" ? "\n" : " ";
72	            i += 1;
73	          }
74	          continue;
75	        }
76	        if (source[i] === quote) {
77	          out += " ";
78	          i += 1;
79	          break;
80	        }
81	        out += source[i] === "\n" ? "\n" : " ";
82	        i += 1;
83	      }
84	      continue;
85	    }
86	    out += ch;
87	    i += 1;
88	  }
89	  return out;
90	}
