92	function tokenize(source) {
93	  const stripped = stripStringsAndComments(source);
94	  const tokens = [];
95	  const re = /0x[0-9A-Fa-f]+|\d+(?:\.\d+)?|[A-Za-z_$][A-Za-z0-9_$]*|=>|===|!==|==|!=|<=|>=|\+\+|--|&&|\|\||[{}()[\].,;:=+\-*/%<>!?]/g;
96	  const lineStarts = [0];
97	  for (let i = 0; i < stripped.length; i += 1) {
98	    if (stripped[i] === "\n") lineStarts.push(i + 1);
99	  }
100	  function position(index) {
101	    let lo = 0;
102	    let hi = lineStarts.length - 1;
103	    while (lo <= hi) {
104	      const mid = Math.floor((lo + hi) / 2);
105	      if (lineStarts[mid] <= index) lo = mid + 1;
106	      else hi = mid - 1;
107	    }
108	    const lineIndex = Math.max(0, hi);
109	    return { line: lineIndex + 1, column: index - lineStarts[lineIndex] + 1 };
110	  }
111	  let match;
112	  while ((match = re.exec(stripped))) {
113	    tokens.push({ value: match[0], index: match.index, ...position(match.index) });
114	  }
115	  return tokens;
116	}
