367	function resolveRef(scope, name, projectGlobals) {
368	  if (KNOWN_GLOBALS.has(name) || projectGlobals.has(name)) return true;
369	  let current = scope;
370	  while (current) {
371	    if (current.declarations.has(name)) return true;
372	    current = current.parent;
373	  }
374	  return false;
375	}
