377	function collectUnresolved(scope, projectGlobals, errors) {
378	  for (const ref of scope.refs) {
379	    if (!resolveRef(scope, ref.value, projectGlobals)) {
380	      errors.push(`${path.relative(ROOT, scope.file)}:${ref.line}:${ref.column} '${ref.value}' is not defined`);
381	    }
382	  }
383	  for (const child of scope.children) collectUnresolved(child, projectGlobals, errors);
384	}
