423	function checkElevatorContract(evalDir) {
424	  const errors = [];
425	  if (!path.basename(evalDir).includes("elevator_prompt_wiggum")) return errors;
426	
427	  const indexPath = path.join(evalDir, "index.html");
428	  const personPath = path.join(evalDir, "person.js");
429	  const elevatorPath = path.join(evalDir, "elevator.js");
430	  const hasElevatorFiles = [indexPath, personPath, elevatorPath].some((filePath) => fs.existsSync(filePath));
431	  if (!hasElevatorFiles) return errors;
432	
433	  for (const filePath of [indexPath, personPath, elevatorPath]) {
434	    if (!fs.existsSync(filePath)) {
435	      errors.push(`${path.relative(ROOT, filePath)}: required elevator artifact is missing`);
436	    }
437	  }
438	  if (errors.length) return errors;
439	
440	  const index = readIfExists(indexPath);
441	  const person = readIfExists(personPath);
442	  const elevator = readIfExists(elevatorPath);
443	  const allCode = `${index}\n${person}\n${elevator}`;
444	  const strippedPerson = stripForContract(person);
445	  const strippedElevator = stripForContract(elevator);
446	
447	  const scriptSrcs = [];
448	  const scriptRe = /<script\b([^>]*)\bsrc\s*=\s*["']([^"']+)["']([^>]*)>\s*<\/script>/gi;
449	  let scriptMatch;
450	  while ((scriptMatch = scriptRe.exec(index))) {
451	    const attrs = `${scriptMatch[1]} ${scriptMatch[3]}`;
452	    scriptSrcs.push({ src: scriptMatch[2], attrs });
453	  }
454	  const expectedScripts = [
455	    "https://cdn.jsdelivr.net/npm/three@0.147.0/build/three.min.js",
456	    "https://cdn.jsdelivr.net/npm/three@0.147.0/examples/js/controls/OrbitControls.js",
457	    "person.js",
458	    "elevator.js",
459	  ];
460	  const actualScripts = scriptSrcs.map((item) => item.src);
461	  if (JSON.stringify(actualScripts) !== JSON.stringify(expectedScripts)) {
462	    errors.push(`${path.relative(ROOT, indexPath)}: script src order must exactly be Three 0.147.0, OrbitControls, person.js, elevator.js`);
463	  }
464	  for (const item of scriptSrcs) {
465	    if (/\btype\s*=\s*["']module["']/i.test(item.attrs)) {
466	      errors.push(`${path.relative(ROOT, indexPath)}: classic scripts required; remove type="module"`);
467	    }
468	  }
469	  const extraLocalScripts = actualScripts.filter((src) => !src.includes("://") && !["person.js", "elevator.js"].includes(src));
470	  if (extraLocalScripts.length) {
471	    errors.push(`${path.relative(ROOT, indexPath)}: unexpected local script(s): ${extraLocalScripts.join(", ")}`);
472	  }
473	
474	  const forbiddenPatterns = [
475	    [/\bimport\b/m, "import"],
476	    [/\bexport\b/m, "export"],
477	    [/\btype\s*=\s*["']module["']/im, "type=\"module\""],
478	    [/file:\/\//i, "file://"],
479	    [/summary\.html/i, "summary.html"],
480	    [/<\s*iframe\b/i, "<iframe"],
481	    [/<\s*object\b/i, "<object"],
482	    [/<\s*embed\b/i, "<embed"],
483	  ];
484	  for (const [pattern, label] of forbiddenPatterns) {
485	    if (pattern.test(allCode)) errors.push(`elevator contract: forbidden ${label} found`);
486	  }
487	
488	  const requiredConstants = new Map([
489	    ["FLOOR_HEIGHT", "3"],
490	    ["FLOOR_COUNT", "6"],
491	    ["BUILDING_WIDTH", "20"],
492	    ["BUILDING_DEPTH", "15"],
493	    ["SHAFT_WIDTH", "5"],
494	    ["SHAFT_DEPTH", "5"],
495	    ["ELEVATOR_SPEED", "2"],
496	    ["PERSON_MOVE_SPEED", "1"],
497	  ]);
498	  for (const [name, value] of requiredConstants.entries()) {
499	    const re = new RegExp(`(^|\\n)\\s*const\\s+${name}\\s*=\\s*${value}\\s*;`);
500	    if (!re.test(strippedElevator)) {
501	      errors.push(`${path.relative(ROOT, elevatorPath)}: missing top-level "const ${name} = ${value};"`);
502	    }
503	  }
504	
505	  const requiredGlobals = [
506	    ["scene", /(^|\n)\s*let\s+scene\s*;/],
507	    ["camera", /(^|\n)\s*let\s+camera\s*;/],
508	    ["renderer", /(^|\n)\s*let\s+renderer\s*;/],
509	    ["controls", /(^|\n)\s*let\s+controls\s*;/],
510	    ["elevatorCar", /(^|\n)\s*let\s+elevatorCar\s*;/],
511	    ["people", /(^|\n)\s*let\s+people\s*=\s*\[\s*\]\s*;/],
512	  ];
513	  for (const [name, pattern] of requiredGlobals) {
514	    if (!pattern.test(strippedElevator)) {
515	      errors.push(`${path.relative(ROOT, elevatorPath)}: missing required top-level global "let ${name}"`);
516	    }
517	  }
518	
519	  for (const forbidden of ["scene", "camera", "renderer", "controls", "elevatorCar", "people"]) {
520	    const re = new RegExp(`(^|\\n)\\s*(?:let|const|var)\\s+${forbidden}\\b`);
521	    if (re.test(strippedPerson)) {
522	      errors.push(`${path.relative(ROOT, personPath)}: must not declare ${forbidden}`);
523	    }
524	  }
525	  if (!/(^|\n)\s*function\s+createPerson\s*\(\s*color\s*\)/.test(strippedPerson)) {
526	    errors.push(`${path.relative(ROOT, personPath)}: must define global function createPerson(color)`);
527	  }
528	  for (const required of ["leftLeg", "rightLeg", "isWalking"]) {
529	    if (!new RegExp(`\\b${required}\\b`).test(strippedPerson)) {
530	      errors.push(`${path.relative(ROOT, personPath)}: createPerson userData must include ${required}`);
531	    }
532	  }
533	  if (!/new\s+THREE\.Group\s*\(/.test(strippedPerson) || !/return\s+[A-Za-z_$][A-Za-z0-9_$]*\s*;/.test(strippedPerson)) {
534	    errors.push(`${path.relative(ROOT, personPath)}: createPerson must create and return a THREE.Group`);
535	  }
536	
537	  if (!/new\s+THREE\.Group\s*\(/.test(strippedElevator) || !/elevatorCar\s*=/.test(strippedElevator)) {
538	    errors.push(`${path.relative(ROOT, elevatorPath)}: elevatorCar must be assigned a THREE.Group`);
539	  }
540	  if (!/elevatorCar\.leftDoor\s*=\s*leftDoor\s*;/.test(strippedElevator)) {
541	    errors.push(`${path.relative(ROOT, elevatorPath)}: must store left door as elevatorCar.leftDoor = leftDoor;`);
542	  }
543	  if (!/elevatorCar\.rightDoor\s*=\s*rightDoor\s*;/.test(strippedElevator)) {
544	    errors.push(`${path.relative(ROOT, elevatorPath)}: must store right door as elevatorCar.rightDoor = rightDoor;`);
545	  }
546	  if (!/elevatorCar\.attach\s*\(/.test(strippedElevator)) {
547	    errors.push(`${path.relative(ROOT, elevatorPath)}: boarding must use elevatorCar.attach(...) to preserve world position`);
548	  }
