478	    while (step > 0 && agent._pathIdx < path.length) {
479	        const tgt = path[agent._pathIdx];
480	        const dx = tgt.x - agent.group.position.x;
481	        const dz = tgt.z - agent.group.position.z;
482	        const dist = Math.sqrt(dx * dx + dz * dz);
483	        if (dist < 0.08) { agent._pathIdx += 1; continue; }
484	        const move = Math.min(step, dist);
485	        agent.group.position.x += dx / dist * move;
486	        agent.group.position.z += dz / dist * move;
487	        agent.group.rotation.y = Math.atan2(dx, dz);
488	        step -= move;
489	    }
