491	    if (moved < 0.005 && dt > 0 && agent._pathIdx < path.length) {
492	        agent._stallT += dt;
493	        if (agent._stallT > 1.2) { agent._pathIdx += 1; agent._stallT = 0; }
494	    } else {
495	        agent._stallT = 0;
496	    }
497	    return agent._pathIdx >= path.length;
498	}
