43	function bfsPath(nodes, fromName, toName) {
44	    if (!nodes[fromName] || !nodes[toName]) return [];
45	    if (fromName === toName) return [nodes[fromName].pos.clone()];
46	    const prev = {};
47	    const seen = {};
48	    seen[fromName] = true;
49	    const queue = [fromName];
50	    let found = false;
51	    while (queue.length) {
52	        const cur = queue.shift();
