function animate() {
    requestAnimationFrame(animate);
    try {
    const realDt = Math.min(0.05, Clock.getDelta());
    Clock.tick(realDt);
    updateLighting();
    const motionDt = realDt * Clock.timeScale;
    try { elevator.tick(motionDt); } catch (e) { console.error("DBG elevator.tick:", e.message); throw e; }
    topUpVisitors();
    for (let i = 0; i < agents.length; i += 1) {
        const a = agents[i];
        if (a.state === "DISABLED" || a.state === "GONE") continue;
        try { processSchedule(a); } catch (e) { console.error("DBG processSchedule id=" + a.id + ":", e.message); throw e; }
        if (a.state !== "GONE" && a.state !== "DISABLED" && a.group.parent) {
            try { dispatch(a, motionDt); } catch (e) { console.error("DBG dispatch id=" + a.id + " state=" + a.state + " planIdx=" + a.planIndex + ":", e.message); throw e; }
        }
    }
    try { applyCollisions(); } catch (e) { console.error("DBG applyCollisions:", e.message); throw e; }
    for (let i = 0; i < agents.length; i += 1) {
        if (agents[i].group.parent) animatePersonWalking(agents[i].group, motionDt);
    }
    controls.update();
    renderer.render(scene, camera);
    updateHUD();
    } catch (e) { console.error("DBG animate outer:", e.message); }
}

